			x, y = q.popleft()

			for x0, y0 in zip(dx, dy):
				if ok(x + x0, y + y0) and dist[x][y] + 1 < dist[x + x0][y + y0]:
					dist[x + x0][y + y0] = dist[x][y] + 1
					q.append((x + x0, y + y0))		

