def findPrime(N):
    if N < 0:
        return -1
    i = N
    while True:
        if isPrime(i):
            return i
        i += 1

def divisors(N):
    pf = primeFactor(N)
    ret = [1]
    for p in pf:
        ret_prev = ret
        ret = []
        for i in range(pf[p]+1):
            for r in ret_prev:
                ret.append(r * (p ** i))
    return sorted(ret)

def mxpow(m, a, e):
    if e == 1:
        return a
    if e % 2 == 0:
        tmp = mxpow(m, a, e//2)
        return mxprod(m, tmp, tmp)
    else:
        tmp = mxpow(m, a, e//2)
        return mxprod(m, mxprod(m, tmp, tmp), a)

def mxprod(m, a, b):
    ret = [[0]*m for _ in range(m)]
    for i in range(m):
        for j in range(m):
            for k in range(m):
                ret[i][j] += a[i][k] * b[k][j]
                ret[i][j] %= P
    return ret

def mxv(m, a, v):
    ret = [0]*m
    for i in range(m):
        for k in range(m):
            ret[i] += a[i][k] * v[k]
            ret[i] %= P
    return ret

def mx(m):
    ret = [[0]*m for _ in range(m)]
    for i in range(m):
        for j in range(i, m):
            ret[i][j] = inv(j+1)

    return ret

def vc(m):
    return [0] * (m-1) + [1]


def inv(a):
    return pow(a, P-2, P)


