def check_mask(mask):
	dp = [[False for j in range(n + 1)] for i in range(k + 1)]

	for j in range(1, n - k + 1 + 1):
		dp[1][j] = (iais[j] & mask == mask)
	if not any(dp[1]):
		return False

	for i in range(2, k + 1):
