def dp():
	dparr = [0] * len(sections)
	for i in range(len(sections) - 1, -1, -1):
		_, curend, curcomfort = sections[i]
		nextsection = i + 1
		try:
			while sections[nextsection][0] <= curend:
				nextsection += 1
		except IndexError:
			# Loop til end
			inc = curcomfort
		else:
			inc = curcomfort + dparr[nextsection]
		exc = 0 if i == len(sections) - 1 else dparr[i + 1]
		dparr[i] = max(inc, exc)
	return dparr[0]


