def get(x):
    if x <= k:
        return x * (x + 1) // 2
    res = k * x - k * (k - 1) // 2
    sz = x - k - 1
    if sz % 2 == 0:
        cnt = sz // 2
        res += (2 + sz) * cnt // 2
    else:
        cnt = sz // 2 + 1
        res += (1 + sz) * cnt // 2
    return res


