def dfs():
    dep = [0] * (n + 1)
    par = [0] * (n + 1)
    mk = [0] * (n + 1)
    st = [1]
    st2 = []
    while st:
        u = st.pop()
        if dep[u]:
            continue
        st2.append(u)
        dep[u] = dep[par[u]] + 1
        for v in g[u]:
            if not dep[v]:
                par[v] = u
                st.append(v)
            elif dep[u] - dep[v] + 1 >= req:
                ans = []
                while u != par[v]:
                    ans.append(u)
                    u = par[u]
                return (None, ans)
    while st2:
        u = st2.pop()
        if not mk[u]:
            for v in g[u]:
                if dep[v] < dep[u]:
                    mk[v] = 1
    return ([u for u in range(1, n + 1) if not mk[u]][:req], None)

