n, vl = list(map(int, input().split()))

def leftinterval(x0, v0, t):
    if x0 / v0 <= t:
        return (0, 10**6)
    if x0 / (vl + v0) > t:
        return (-1, -2)
    leftbound = x0
    rightbound = (vl * vl - v0 * v0) * t + x0 * v0
    rightbound /= vl
    rightbound = int(rightbound)
    if rightbound > 10**6:
        rightbound = 10**6
    return (leftbound, rightbound)
def rightinterval(x0, v0, t):
    if (10**6 - x0) / v0 <= t:
        return (0, 10**6)
    if (10**6 - x0) / (v0 + vl) > t:
        return (-1, -2)
    rightbound = x0
    leftbound = v0 * x0 + (10**6) * (vl - v0) - t * (vl * vl - v0 * v0)
    leftbound /= vl
    leftbound = math.ceil(leftbound)
    if(leftbound < 0):
        leftbound = 0
    return (leftbound, rightbound)

