class Solution:
     def permute(self, nums):
         """
         :type nums: List[int]
         :rtype: List[List[int]]
         """
         all_permutes = []
         self.permute_nums(all_permutes, nums, [])
         return all_permutes

     def permute_nums(self, all_permutes, nums, cur_permute):
         if len(nums) == 0:
             all_permutes.append(cur_permute)
             return

         for i in range(len(nums)):
             num = nums[i]

             self.permute_nums(all_permutes, nums[0:i] + nums[i+1:len(nums)], cur_permute + [num])

class Solution:
    def longestValidParentheses(self, s: str) -> int:
        memo ={}
        n =len(s)
        def dp(i):
            if i<=0:
                return 0
            if i in memo:
                return memo[i]
            if (s[i-1],s[i])==('(',')'):
                memo[i]=dp(i-2)+2
            elif (s[i-1],s[i])==(')',')') and i-dp(i-1)-1>=0 and s[i-dp(i-1)-1]=='(':
                memo[i]=dp(i-1)+2+dp(i-dp(i-1)-2)
            else:
                memo[i]=0
            return memo[i]
        ret = 0
        for i in range(n-1,0,-1):
            ret = max(ret, dp(i))
        return ret

class Solution:
     def majorityElement(self, nums):
         """
         :type nums: List[int]
         :rtype: int
         """

         if nums == []:
             return []

         dct = {}
         for el in nums:
             if el in dct:
                 dct[el] += 1
             else:
                 dct[el] = 1

         fin = []
         for key in dct:
             if dct[key] > (len(nums) // 3):
                 fin.append(key)

         return fin

import bisect
from functools import lru_cache


class Solution:
    def makeArrayIncreasing(self, A: List[int], B: List[int]) -> int:
        B = sorted(set(B))

        @lru_cache(None)
        def find_larger_value_in_B(val):
            if val >= B[-1]:
                return float('inf')
            return B[bisect.bisect_right(B, val)]

        @lru_cache(None)
        def min_last_value_given_operations(n, ops):
            if ops < 0:
                return float('inf')
            elif n == 0:
                return float('-inf')
            elif ops > n:
                return min_last_value_given_operations(n, n)

            prev_with_op = min_last_value_given_operations(n - 1, ops - 1)
            b = find_larger_value_in_B(prev_with_op)
            # dp(n - 1, ops) <= dp(n - 1, ops - 1)
            # if dp(n - 1, ops - 1) < A[n - 1] => dp(n - 1, ops) < A[n - 1]
            if prev_with_op < A[n - 1]:
                return min(A[n - 1], b)
            elif b <= A[n - 1]:
                return b
            elif min_last_value_given_operations(n - 1, ops) < A[n - 1]:
                return A[n - 1]
            return b

        last_success = -1
        for ops in range(min(len(A), len(B)), -1, -1):
            if min_last_value_given_operations(len(A), ops) == float('inf'):
                break
            last_success = ops

        return last_success

