class Solution:
     def maximalRectangle(self, matrix):
         """
         :type matrix: List[List[str]]
         :rtype: int
         """
         if not matrix or not matrix[0]:
             return 0
         n = len(matrix[0])
         height = [0] * (n + 1)
         ans = 0
         for row in matrix:
             for i in range(n):
                 height[i] = height[i] + 1 if row[i] == '1' else 0
             stack = [-1]
             for i in range(n + 1):
                 while height[i] < height[stack[-1]]:
                     h = height[stack.pop()]
                     w = i - 1 - stack[-1]
                     ans = max(ans, h * w)
                 stack.append(i)
         return ans

class Solution:
     def grayCode(self, n):
         """
         :type n: int
         :rtype: List[int]
         """
         res = []
         for i in range(1<<n):
             res.append(i ^ i >>1)
         return res

class Solution:
     def uniquePathsWithObstacles(self, obstacleGrid):
         """
         :type obstacleGrid: List[List[int]]
         :rtype: int
         """
         m = len(obstacleGrid) #row
         n = len(obstacleGrid[0]) #col
         path = [[0 for j in range(n)] for i in range(m)]
         for i in range(m):
             if obstacleGrid[i][0] == 0:
                 path[i][0] = 1
             else:
                 break
         for i in range(n):
             if obstacleGrid[0][i] == 0:
                 path[0][i] = 1
             else:
                 break
         for i in range(1,m):
             for j in range(1,n):
                 if obstacleGrid[i][j] != 1:
                     path[i][j] = path[i-1][j] + path[i][j-1]
                 else:
                     path[i][j] = 0
         return path[m-1][n-1]

