ll power(ll x,ll y){
    ll res=1;
    while (y){
        if (y & 1){
            res=res*x; 
        }
        x=x*x;
        y=y>>1;
    }
    return res;
}
ll cube(ll x){
    ll res=x,sum=0;
    while(x!=0){
        sum+=(x%10);
        x=x/10;
    }
    res+=power(sum,3);
    return res;
}
ll max_xp(int i,int r){
    if(i>n){
        return 0;
    }
    if(dp[i][r]!=-1){
        return dp[i][r];
    }
    ll maxi=0;
    if(r<=n){
        maxi=max_xp(i+1,r+1);
    }
    maxi=max(maxi,max_xp(i+1,r)+xp[i]*train[r]);
    return dp[i][r]=maxi;
}
