def f(t, k):
    i, j = 0, 1
    s, d = 0, t[0]
    n = len(t)
    while j <= n:
        if d > k:
            d -= t[i]
            i += 1
        elif d == k:
            if t[i] and (j == n or t[j]): s += 1
            else:
                a, b = i - 1, j - 1
                while j < n and t[j] == 0: j += 1
                while t[i] == 0: i += 1
                s += (i - a) * (j - b)
            if j < n: d += t[j]
            d -= t[i]
            i += 1
            j += 1                
        else:
            if j < n: d += t[j]
            j += 1
    return s

