class Solution:
    def reverseBits(self, n: int) -> int:
        rev = ''
        for i in reversed(bin(n)[2:]):
            rev = rev + i
        rev = rev + '0'*(32-len(rev)) 

        return int(rev, 2)

class Solution:
     def generate(self, numRows):
         """
         :type numRows: int
         :rtype: List[List[int]]
         """
         res = [[1]]
         for i in range(1,numRows):
             res.append(list(map(lambda x, y : x + y, res[-1]+[0], [0]+res[-1])))
         return res[:numRows]

